# Not age-based either: the signal is the rule state today (over cap, a dated step
# missed, a checkpoint missed, a charter missing a receiver). And a check that
# FAILS must not read as OK - a silent pass is the invisible absence this script
# was written to catch.
$slateStatus = "DUE"
$slateWhy = ""
try {
    $slateArgs = @($PortfolioScript, "slate-check", "--json", "--today", $today.ToString('yyyy-MM-dd'))
    if ($SlateRegistry) { $slateArgs += @("--registry", $SlateRegistry) }
    $raw = & $Python @slateArgs 2>&1 | Out-String
    if ($LASTEXITCODE -ne 0) { throw "slate-check exited $LASTEXITCODE - $($raw.Trim())" }
    $slate = $raw | ConvertFrom-Json
    $slateStatus = $slate.status
    $slateWhy = if (-not $slate.enabled) {
                    "slate not configured in portfolio.json (meta.slate missing)"
                } elseif (@($slate.problems).Count -eq 0) {
                    "$($slate.active) of $($slate.cap) active, every step on date"
                } else {
                    (@($slate.problems) | Select-Object -First 3 | ForEach-Object { "$($_.project): $($_.message)" }) -join " | "
                }
}
catch {
    $slateWhy = "slate check could not run: $_"
}
$rituals += [pscustomobject]@{
    Name    = "slate"
    Command = "python3 ~/DEV/project-triage/portfolio.py slate-check"
    Last    = $today.ToString('yyyy-MM-dd')
    Days    = 0
    Status  = $slateStatus
    Why     = $slateWhy
}

if ($Json) {
    $rituals | ConvertTo-Json -Depth 4
    exit 0
}

