# tests/keystone-ritual-slate.ps1
#
# The slate entry forwards project-triage's slate-check verdict. The rules
# themselves are tested in project-triage (tests/test_slate.py); these tests pin
# the wiring, and above all that a check which CANNOT RUN never reads as OK. A
# silent pass is exactly the invisible absence ritual-check exists to surface.
$ErrorActionPreference = "Stop"
function Assert-True($Condition, $Message) { if (-not $Condition) { throw $Message } }
$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..")
$script = Join-Path $repoRoot "scripts/ritual-check.ps1"
$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("keystone-slate-test-" + [System.Guid]::NewGuid().ToString("n"))
New-Item -ItemType Directory -Force -Path $tempRoot | Out-Null
$today = [datetime]'2026-10-01'

function New-Registry {
    param([int]$Active, [string]$Receiver = "Kenny Boyd", [string]$Step2Due = "2026-10-15")
    $projects = @()
    for ($i = 1; $i -le $Active; $i++) {
        $projects += @{
            name = "P$i"; lane = "job"; rank = $i; status = "active"; purpose = "p"; next_action = "n"
            charter = @{
                pillar = "data"; jd_duty = "Technology oversight"; receiver = $Receiver
                done_means = "report delivered"; finish_by = "2026-11-30"
                steps = @(
                    @{ name = "Plan agreed"; due = "2026-09-20"; done = "2026-09-19" },
                    @{ name = "First draft"; due = $Step2Due; done = $null },
                    @{ name = "Final delivered"; due = "2026-11-15"; done = $null },
                    @{ name = "In use"; due = "2026-11-30"; done = $null }
                )
            }
        }
    }
    $reg = @{
        meta = @{ artifact_url = ""; slate = @{ cap = 4; semester_close = "2026-12-18"; next_up = @(); checkpoints = @() } }
        projects = $projects; ideas = @()
    }
    $path = Join-Path $tempRoot ([System.Guid]::NewGuid().ToString("n") + ".json")
    $reg | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $path -Encoding UTF8
    $path
}

function Get-Slate {
    param([string]$Registry, [string]$PortfolioScript = "")
    $extra = @{}
    if ($PortfolioScript) { $extra.PortfolioScript = $PortfolioScript }
    $out = & $script -Json -Today $today -SlateRegistry $Registry -Vault $tempRoot -CfbSnapshotDir $tempRoot @extra 2>&1 | Out-String
    ($out | ConvertFrom-Json) | Where-Object { $_.Name -eq 'slate' }
}

try {
    $s = Get-Slate (New-Registry -Active 3)
    Assert-True ($null -ne $s) "slate must appear in the ritual list."
    Assert-True ($s.Status -eq 'OK') "A healthy slate must be OK, got '$($s.Status)': $($s.Why)"
    Assert-True ($s.Why -match '3 of 4') "OK must say how full the slate is; got '$($s.Why)'."

    $s = Get-Slate (New-Registry -Active 5)
    Assert-True ($s.Status -eq 'OVERDUE') "Over the cap must be OVERDUE, got '$($s.Status)'."
    Assert-True ($s.Why -match 'cap is 4') "Why must name the cap; got '$($s.Why)'."

    $s = Get-Slate (New-Registry -Active 2 -Step2Due "2026-09-25")
    Assert-True ($s.Status -eq 'OVERDUE') "A missed step must be OVERDUE, got '$($s.Status)'."
    Assert-True ($s.Why -match 'First draft') "Why must name the late step; got '$($s.Why)'."

    $s = Get-Slate (New-Registry -Active 1 -Receiver "")
    Assert-True ($s.Status -eq 'DUE') "No receiver must be DUE, got '$($s.Status)'."

    # THE DISCRIMINATING CASE: the checker cannot run. An implementation that
    # defaults to OK on failure passes every case above and fails this one.
    $s = Get-Slate (New-Registry -Active 1) -PortfolioScript (Join-Path $tempRoot "missing.py")
    Assert-True ($s.Status -ne 'OK') "A slate check that cannot run must not read as OK, got '$($s.Status)'."
    Assert-True ($s.Why -match 'could not run') "Why must say the check failed; got '$($s.Why)'."

    Write-Host "keystone ritual slate tests passed"
}
finally { if (Test-Path $tempRoot) { Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } }

